// Method: XRInterface::get_transform_for_view
static JSValue js_XRInterface_get_transform_for_view(JSContext* ctx, JSValueConst this_val, int argc, JSValueConst* argv) {
    if (argc < 1) {
        return JS_ThrowTypeError(ctx, "XRInterface.get_transform_for_view: missing handle argument");
    }

    int64_t handle;
    if (JS_ToInt64(ctx, &handle, argv[0]) < 0) {
        return JS_ThrowTypeError(ctx, "XRInterface.get_transform_for_view: invalid handle");
    }

    QuickJSContext* qjs_ctx = get_qjs_ctx(ctx);
    if (!qjs_ctx || !qjs_ctx->get_object_registry()) {
        return JS_ThrowInternalError(ctx, "Context not initialized");
    }


    Object* obj = qjs_ctx->get_object_registry()->get_object(handle);
    if (!obj) {
        return JS_ThrowTypeError(ctx, "XRInterface.get_transform_for_view: invalid or freed object");
    }

    XRInterface* typed_obj = Object::cast_to<XRInterface>(obj);
    if (!typed_obj) {
        return JS_ThrowTypeError(ctx, "XRInterface.get_transform_for_view: object is not a XRInterface");
    }

    // Argument count check (excluding handle) - only required args
    if (argc < 3) {
        return JS_ThrowTypeError(ctx, "XRInterface.get_transform_for_view: expected at least 2 arguments, got %d", argc - 1);
    }

    // Convert arguments
    int64_t arg_view; JS_ToInt64(ctx, &arg_view, argv[1]);
    Transform3D arg_cam_transform;
    JSValue jbasis_cam_transform = JS_GetPropertyStr(ctx, argv[2], "basis");
    JSValue jorigin_cam_transform = JS_GetPropertyStr(ctx, argv[2], "origin");
    if (!JS_IsUndefined(jorigin_cam_transform)) {
        double ox, oy, oz;
        JSValue jox_cam_transform = JS_GetPropertyStr(ctx, jorigin_cam_transform, "x");
        JSValue joy_cam_transform = JS_GetPropertyStr(ctx, jorigin_cam_transform, "y");
        JSValue joz_cam_transform = JS_GetPropertyStr(ctx, jorigin_cam_transform, "z");
        JS_ToFloat64(ctx, &ox, jox_cam_transform);
        JS_ToFloat64(ctx, &oy, joy_cam_transform);
        JS_ToFloat64(ctx, &oz, joz_cam_transform);
        arg_cam_transform.origin = Vector3(ox, oy, oz);
        JS_FreeValue(ctx, jox_cam_transform); JS_FreeValue(ctx, joy_cam_transform); JS_FreeValue(ctx, joz_cam_transform);
    }
    if (!JS_IsUndefined(jbasis_cam_transform)) {
        JSValue jbx_cam_transform = JS_GetPropertyStr(ctx, jbasis_cam_transform, "x");
        JSValue jby_cam_transform = JS_GetPropertyStr(ctx, jbasis_cam_transform, "y");
        JSValue jbz_cam_transform = JS_GetPropertyStr(ctx, jbasis_cam_transform, "z");
        if (!JS_IsUndefined(jbx_cam_transform) && !JS_IsUndefined(jby_cam_transform) && !JS_IsUndefined(jbz_cam_transform)) {
            double xx, xy, xz, yx, yy, yz, zx, zy, zz;
            JSValue jbxx = JS_GetPropertyStr(ctx, jbx_cam_transform, "x"); JSValue jbxy = JS_GetPropertyStr(ctx, jbx_cam_transform, "y"); JSValue jbxz = JS_GetPropertyStr(ctx, jbx_cam_transform, "z");
            JSValue jbyx = JS_GetPropertyStr(ctx, jby_cam_transform, "x"); JSValue jbyy = JS_GetPropertyStr(ctx, jby_cam_transform, "y"); JSValue jbyz = JS_GetPropertyStr(ctx, jby_cam_transform, "z");
            JSValue jbzx = JS_GetPropertyStr(ctx, jbz_cam_transform, "x"); JSValue jbzy = JS_GetPropertyStr(ctx, jbz_cam_transform, "y"); JSValue jbzz = JS_GetPropertyStr(ctx, jbz_cam_transform, "z");
            JS_ToFloat64(ctx, &xx, jbxx); JS_ToFloat64(ctx, &xy, jbxy); JS_ToFloat64(ctx, &xz, jbxz);
            JS_ToFloat64(ctx, &yx, jbyx); JS_ToFloat64(ctx, &yy, jbyy); JS_ToFloat64(ctx, &yz, jbyz);
            JS_ToFloat64(ctx, &zx, jbzx); JS_ToFloat64(ctx, &zy, jbzy); JS_ToFloat64(ctx, &zz, jbzz);
            arg_cam_transform.basis = Basis(Vector3(xx, xy, xz), Vector3(yx, yy, yz), Vector3(zx, zy, zz));
            JS_FreeValue(ctx, jbxx); JS_FreeValue(ctx, jbxy); JS_FreeValue(ctx, jbxz);
            JS_FreeValue(ctx, jbyx); JS_FreeValue(ctx, jbyy); JS_FreeValue(ctx, jbyz);
            JS_FreeValue(ctx, jbzx); JS_FreeValue(ctx, jbzy); JS_FreeValue(ctx, jbzz);
        }
        JS_FreeValue(ctx, jbx_cam_transform); JS_FreeValue(ctx, jby_cam_transform); JS_FreeValue(ctx, jbz_cam_transform);
    }
    JS_FreeValue(ctx, jbasis_cam_transform);
    JS_FreeValue(ctx, jorigin_cam_transform);

    Transform3D result = typed_obj->get_transform_for_view(arg_view, arg_cam_transform);
    JSValue ret_obj = JS_NewObject(ctx);
    JSValue basis_obj = JS_NewObject(ctx);
    JSValue origin_obj = JS_NewObject(ctx);
    JSValue bx_obj = JS_NewObject(ctx);
    JSValue by_obj = JS_NewObject(ctx);
    JSValue bz_obj = JS_NewObject(ctx);
    Vector3 col_x = result.basis.get_column(0);
    Vector3 col_y = result.basis.get_column(1);
    Vector3 col_z = result.basis.get_column(2);
    JS_SetPropertyStr(ctx, bx_obj, "x", JS_NewFloat64(ctx, col_x.x));
    JS_SetPropertyStr(ctx, bx_obj, "y", JS_NewFloat64(ctx, col_x.y));
    JS_SetPropertyStr(ctx, bx_obj, "z", JS_NewFloat64(ctx, col_x.z));
    JS_SetPropertyStr(ctx, by_obj, "x", JS_NewFloat64(ctx, col_y.x));
    JS_SetPropertyStr(ctx, by_obj, "y", JS_NewFloat64(ctx, col_y.y));
    JS_SetPropertyStr(ctx, by_obj, "z", JS_NewFloat64(ctx, col_y.z));
    JS_SetPropertyStr(ctx, bz_obj, "x", JS_NewFloat64(ctx, col_z.x));
    JS_SetPropertyStr(ctx, bz_obj, "y", JS_NewFloat64(ctx, col_z.y));
    JS_SetPropertyStr(ctx, bz_obj, "z", JS_NewFloat64(ctx, col_z.z));
    JS_SetPropertyStr(ctx, basis_obj, "x", bx_obj);
    JS_SetPropertyStr(ctx, basis_obj, "y", by_obj);
    JS_SetPropertyStr(ctx, basis_obj, "z", bz_obj);
    JS_SetPropertyStr(ctx, origin_obj, "x", JS_NewFloat64(ctx, result.origin.x));
    JS_SetPropertyStr(ctx, origin_obj, "y", JS_NewFloat64(ctx, result.origin.y));
    JS_SetPropertyStr(ctx, origin_obj, "z", JS_NewFloat64(ctx, result.origin.z));
    JS_SetPropertyStr(ctx, ret_obj, "basis", basis_obj);
    JS_SetPropertyStr(ctx, ret_obj, "origin", origin_obj);
    return ret_obj;
}

